// The entries above whose tags no longer appear in BANKS (MC-HIST-01 to
// -13, MC-CRIM-01, MC-LAW-02) come from History and Criminology banks that
// were replaced. They are kept for the same reason MC_LABELS keeps retired
// tags: rows in the `responses` table still reference them, so a teacher
// looking at last year's data should still get the starter, not a bare code.

// ---- Structured fallback builders ---------------------------------------
// These builders are intentionally small. They use the live question and
// scaffold so a low-use tag still gets a useful, misconception-specific task
// without adding hundreds of near-identical literal entries.
function _mcStarterQuestion(tag) {
  if (typeof BANKS === 'undefined') return null;
  for (var bankId in BANKS) {
    var questions = BANKS[bankId] && BANKS[bankId].questions || [];
    for (var i = 0; i < questions.length; i++) {
      var questionTags = Array.isArray(questions[i].tag) ? questions[i].tag : [questions[i].tag];
      if (questionTags.indexOf(tag) !== -1) return questions[i];
    }
  }
  return null;
}

function _mcStarterHash(value) {
  var hash = 0;
  var text = String(value || '');
  for (var i = 0; i < text.length; i++) hash = (hash * 31 + text.charCodeAt(i)) >>> 0;
  return hash;
}

function _mcStarterText(question) {
  return question ? String(question.stem || '').replace(/\s+/g, ' ').trim() : '';
}

function _mcStarterScaffold(question) {
  return question ? String(question.scaffold || '').replace(/\s+/g, ' ').trim() : '';
}

function _mcStarterInfer(question) {
  var stem = _mcStarterText(question).toLowerCase();
  var scaffold = _mcStarterScaffold(question).toLowerCase();
  var text = (stem + ' ' + scaffold).trim();

  // Choose the activity from the student's likely error, not just from the
  // subject. The order matters: a question can mention a formula while
  // actually testing a process, and a scenario can still be a calculation.
  if (/\b(calculate|work out|compute|use .*formula|find the (?:value|gradient|percentage|probability|ratio|mean|magnification|velocity|force|energy|power|resistance|rate|profit|revenue|elasticity)|how much|how many|what is the (?:speed|acceleration|current|voltage|power|resistance|percentage|probability))\b/.test(text) || /\b\d+\s*[×x÷%]/.test(text)) return 'calculate';
  if (/\b(draw|sketch|plot|graph|axis|axes|curve|wave|ray|field|circuit|histogram|scatter|diagram|cross-section)\b/.test(text)) return /\b(graph|plot|axis|axes|histogram|scatter)\b/.test(text) ? 'graph' : 'diagram';
  if (/\b(student|learner|candidate)\s+(?:writes?|thinks?|says?|claims?)\b|\b(rewrite|correct|error|incorrect|wrong|fix|faulty|misconception)\b/.test(text)) return /\b(rewrite|sentence|statement)\b/.test(text) ? 'rewrite' : 'correct';
  if (/\b(sequence|order|stages|step-by-step|process|chain|cycle|pathway|transmission|replication|algorithm|how does .* happen|what happens when)\b/.test(text)) return 'sequence';
  if (/\b(compare|difference|versus|\bvs\.?\b|both|whereas|similarit|contrast|paired)\b/.test(text)) return 'compare';
  if (/\b(classif|sort|match|categor|which (?:term|type|category)|label each|distinguish)\b/.test(text)) return /\b(distinguish|difference|vs\.?|compare)\b/.test(text) ? 'distinguish' : 'classify';
  if (/\b(scenario|case study|application|situation|patient|company|business|experiment|new context|in practice|given that)\b/.test(text)) return 'apply';
  if (/\b(why|how)\b/.test(stem) || /\b(mechanism|cause|leads to|results in|because|therefore|explain why)\b/.test(text)) return 'sequence';

  // Short factual prompts are usually terminology or boundary errors. Make
  // students separate the answer from its nearest distractor instead of
  // asking them for an artificial judgement.
  if (/^(what|which|who|where|when|define|identify|name|state)\b/.test(stem) && !/\b(which (?:argument|view|factor|option|response|explanation) (?:is|would be|best)|what is the (?:best|most important))\b/.test(stem)) return 'distinguish';
  if (/\b(what is meant by|what does .* mean|what is the main role|which structure|which memory store|which feature|which term)\b/.test(stem)) return 'distinguish';
  if (/\b(evaluate|assess|to what extent|how far|judg(e|ement)|claim|view|argument|most important)\b/.test(text)) return 'evaluate';
  return 'apply';
}

function _mcStarterTitle(type, name, variant) {
  var titles = {
    calculate: ['Work the misconception', 'Number check', 'Show the method'],
    classify: ['Sort it before you explain it', 'Category check', 'Put the terms in their place'],
    distinguish: ['Draw the boundary', 'Two ideas, one decision', 'Which one is it?'],
    correct: ['Repair the claim', 'Find the faulty step', 'Make the answer defensible'],
    rewrite: ['Rewrite for accuracy', 'Upgrade the answer', 'Words that earn the mark'],
    sequence: ['Build the chain', 'Put the process in motion', 'What happens next?'],
    chain: ['Build the causal chain', 'Link cause to consequence', 'No skipped mechanism'],
    compare: ['Side-by-side check', 'Compare the pair', 'Same or different?'],
    diagram: ['Make the model visible', 'Draw what the words mean', 'Diagram check'],
    graph: ['Read it from the axes', 'Graph the relationship', 'Plot before you predict'],
    apply: ['Use the rule in context', 'Transfer check', 'New situation, same idea'],
    evaluate: ['Commit, then qualify', 'Decide and defend', 'The judgement test']
  };
  var choices = titles[type] || titles.evaluate;
  return choices[variant % choices.length] + (name ? ': ' + name : '');
}

function _mcStarterFallback(tag, label, question) {
  var name = label || (typeof resolveMCLabel === 'function' ? resolveMCLabel(tag) : '') || tag;
  var stem = _mcStarterText(question) || ('the question tagged ' + tag);
  var scaffold = _mcStarterScaffold(question);
  var type = _mcStarterInfer(question);
  var variant = _mcStarterHash(tag);
  var lead = [
    'Commit silently before anyone explains: write your answer and one reason.',
    'Everyone writes first; discussion starts only after every board has an answer.',
    'Choose an answer, then underline the exact word or step that decided it.'
  ][variant % 3];
  var follow = [
    'Teacher move: take one wrong answer, ask which word in the scaffold disproves it, then run the same check on a fresh example.',
    'Teacher move: reveal the governing rule only after the vote; ask one student to repair the most plausible wrong answer aloud.',
    'Teacher move: collect the two most common answers, compare their reasoning, and finish with a one-question recheck.'
  ][variant % 3];
  var task;
  if (type === 'calculate') task = 'Calculate or derive the answer to this question: “' + stem + '” Show the first substitution or operation, then circle the final value and its unit or meaning.';
  else if (type === 'classify' || type === 'distinguish') task = 'Make the decision demanded by this question: “' + stem + '” Write the category or term first, then give one boundary rule that separates it from the nearest alternative.';
  else if (type === 'correct' || type === 'rewrite') task = 'Answer this question: “' + stem + '” Then write the tempting wrong version you would expect from this misconception and cross out the precise part that fails.';
  else if (type === 'sequence' || type === 'chain') task = 'Turn this question into a four-step chain: “' + stem + '” Number the steps, commit to the order, and add the cause or mechanism on each arrow. Circle the first link a wrong answer would break.';
  else if (type === 'compare') task = 'Answer this comparison question: “' + stem + '” Complete two columns: what is true of each idea, and the single feature that keeps them from being interchangeable.';
  else if (type === 'diagram' || type === 'graph') task = 'Answer this visual question: “' + stem + '” Draw or annotate the model before the reveal; label the feature that would change if the common misconception were true.';
  else if (type === 'apply') task = 'Apply the idea to this question: “' + stem + '” State your decision, cite the rule, and predict what would happen if one important condition changed.';
  else task = 'Take a position on this question: “' + stem + '” Give one piece of evidence, one condition that limits it, and a one-sentence judgement.';
  return {type:type, title:_mcStarterTitle(type, name, variant), instruction:lead + ' ' + task + ' ' + follow, prompt:scaffold ? 'Scaffold to revisit after the vote: ' + scaffold : 'After the vote, return to the question wording and identify the clue that supports the answer.'};
}

function _mcCuratedSubject(tag) {
  var groups = [MC_CURATED_TAGS, MC_ADDITIONAL_TAGS];
  for (var g = 0; g < groups.length; g++) for (var subject in groups[g]) {
    if (groups[g][subject].indexOf(tag) !== -1) return subject;
  }
  return '';
}

function _mcCuratedStarter(tag, label, question) {
  var base = _mcStarterFallback(tag, label, question);
  var stem = _mcStarterText(question) || ('the question tagged ' + tag);
  var anchor = {
    calculate:'Students commit to a worked answer, show the first operation, and annotate why the most tempting alternative fails.',
    diagram:'Students commit to a labelled sketch before seeing the model answer, then correct one misplaced label or relationship.',
    graph:'Students commit to the shape and direction of the graph, label both axes, and explain one feature the common error would reverse.',
    sequence:'Students commit to the order of the process, write the mechanism on each arrow, and identify the first step that would make the error inevitable.',
    compare:'Students commit to a two-column comparison, then write one sentence explaining why the paired ideas cannot be swapped.',
    classify:'Students commit to a category for each case, then write the rule that separates the correct category from its nearest distractor.',
    distinguish:'Students commit to the distinction, then give a boundary example that would be misclassified by the common misconception.',
    correct:'Students commit to a correction, then underline the exact word or causal link that makes the original claim wrong.',
    rewrite:'Students commit to a rewritten answer, then mark the added term or qualification that earns the correction mark.',
    apply:'Students commit to a decision in the context, cite the governing rule, and predict what changes when one condition is removed.',
    evaluate:'Students commit to a judgement, support it with one precise concept, and state the condition under which the judgement would change.'
  }[base.type] || 'Students commit to an answer before the reveal, then identify the precise rule that separates it from the common wrong answer.';
  base.title = base.title.replace(/^([^:]+): /, '');
  var opening = [
    'Commit before the reveal: answer this exact question — “' + stem + '” ',
    'Start with a silent answer to “' + stem + '” ',
    'Put one answer on the board for “' + stem + '” before discussion. '
  ][_mcStarterHash(tag) % 3];
  base.instruction = opening + anchor + ' Teacher move: reveal the scaffold only after every student has committed; take the strongest wrong answer and repair the precise step that caused it.';
  return base;
}

function getStarterActivity(tag, label) {
  if (tag && MC_STARTERS[tag]) return MC_STARTERS[tag];
  if (tag && _mcCuratedSubject(tag)) return _mcCuratedStarter(tag, label, _mcStarterQuestion(tag));
  return _mcStarterFallback(tag, label, _mcStarterQuestion(tag));
}


// A-Level Economics stage 2. Hand-authored starters for the tags created by
// the stage 2 retag in econMisconceptionTags. Every aggregatable econ tag
// needs one: econ is listed in TAG_TAXONOMY_SUBJECTS, so dev/audit-banks.js
// fails on any shared tag without an explicit entry.

// Stage 2, Theme 1 microeconomics.
var MC_ECON_STAGE2_MICRO = {
  "MC-MICRO-EQUILIBRIUM":{type:"distinguish",title:"Above, Below, At",instruction:"For each price, state whether there is a surplus or a shortage, which side of the market is rationed, and which way price moves next.",items:["Price above equilibrium", "Price below equilibrium", "Price at equilibrium"],answer:"Above: quantity supplied exceeds quantity demanded, so there is a SURPLUS; sellers are rationed and unsold stock pushes price DOWN. Below: quantity demanded exceeds quantity supplied, a SHORTAGE; buyers are rationed and competition for scarce units pushes price UP. At equilibrium: the two quantities are equal and there is no pressure either way. The error to kill is treating equilibrium as the price the seller wants or the 'fair' price. It is neither — it is simply the only price at which the plans of buyers and sellers are mutually consistent, so nobody has a reason to change what they are doing."},
  "MC-MICRO-XED":{type:"calculate",title:"Substitute or Complement?",instruction:"Compute XED and classify each pair. Write the formula before you start.",items:["Price of coffee +10%, quantity of tea demanded +4%", "Price of printers +10%, quantity of ink cartridges demanded -6%", "Price of bread +10%, quantity of socks demanded 0%"],answer:"XED = %change in quantity demanded of A / %change in price of B. (1) +4/+10 = +0.4, POSITIVE, so substitutes — coffee dearer, buyers switch to tea. (2) -6/+10 = -0.6, NEGATIVE, so complements — printers dearer, fewer printers bought, so less ink. (3) 0/+10 = 0, unrelated. The whole content of the measure is the SIGN: positive means substitutes, negative means complements, zero means unrelated. The size only tells you how strong that relationship is. Students who memorise 'substitutes have high XED' get case 3 wrong."},
  "MC-MICRO-SCARCITY":{type:"correct",title:"The Cost of the Revision Session",instruction:"A student writes: 'The opportunity cost of the three-hour revision session was the £6 bus fare.' Correct it, then state what opportunity cost actually is.",items:["Identify what is wrong", "Give the correct opportunity cost", "State the general rule"],answer:"The £6 is the money price, not the opportunity cost. Opportunity cost is the value of the NEXT BEST alternative forgone — here, the best thing those three hours could have been spent on, such as the paid shift or the revision of another subject. The rule: opportunity cost is measured in forgone alternatives, not in pounds, and there is exactly one of them (the next best), not a list of everything given up. It exists because resources are scarce relative to wants, which is why every choice has one. Connect to factors of production: land earns rent, labour earns wages, capital earns interest, enterprise earns profit."},
  "MC-MICRO-PPF":{type:"diagram",title:"Inside, On, Beyond",instruction:"Sketch a PPF. Mark a point inside, a point on, and a point beyond it, and say what each represents. Then explain the bow.",items:["A point inside the curve", "A point on the curve", "A point beyond the curve"],answer:"Inside: attainable but INEFFICIENT — resources are unemployed or misallocated, so more of both goods could be produced. This is the one students get wrong, calling it impossible. On: attainable and productively efficient; more of one good now requires less of the other, which is opportunity cost made visible. Beyond: unattainable with current resources and technology. The outward bow is NOT caused by scarcity — scarcity is why the curve exists at all. It is caused by factors of production being imperfectly substitutable: as you move resources into one good you transfer progressively less suitable ones, so the opportunity cost of each extra unit rises. Growth shifts the whole curve outward."},
  "MC-MICRO-SPECIALISATION":{type:"chain",title:"Why Output Rises, and What It Costs",instruction:"Build the causal chain from specialisation to higher output. Then give one genuine risk.",items:["Workers repeat a narrower task", "Skill and speed at that task rise", "Less time lost switching between tasks", "Total output per worker rises"],answer:"The chain matters more than the claim: narrower task, so more practice per unit time, so higher skill and speed, plus less time lost switching between operations and more scope to use specialised capital — therefore output per worker rises and unit costs fall. An answer that just asserts 'specialisation raises output' scores nothing; the mechanism IS the mark. The risks: over-dependence, so a demand shift or supply shock leaves workers with narrow, non-transferable skills; monotony reducing motivation and quality; and at country level, reliance on one export exposes the economy to a single price. Specialisation raises potential output and raises exposure at the same time."},
  "MC-MICRO-SUPPLY-DETERMINANTS":{type:"classify",title:"Along, or Shift?",instruction:"Sort each change into MOVEMENT ALONG the supply curve or SHIFT of the supply curve, and say which way.",items:["The market price of wheat rises", "Bad weather destroys part of the harvest", "A subsidy is paid to producers", "Wages of farm workers rise"],answer:"Movement ALONG: only a change in the good's OWN price. So the wheat price rising is a movement up the curve — an extension of supply. SHIFT: everything else. Bad weather shifts supply LEFT (less can be produced at every price). A subsidy shifts it RIGHT, since costs per unit fall. Higher wages shift it LEFT. The test is one question: did the good's own price change, or did the conditions of production change? Own price means you slide along the existing curve; anything else means you draw a new one. The law of supply — higher price, more supplied — describes the shape of the curve, not a reason to redraw it."},
  "MC-MICRO-YED":{type:"classify",title:"Normal, Luxury, Inferior",instruction:"Classify each good from its YED and state what happens to demand as income rises.",items:["YED = +0.4", "YED = +2.1", "YED = -0.7"],answer:"YED = %change in quantity demanded / %change in income. +0.4: normal and income-INELASTIC, a necessity — demand rises with income but proportionally less. +2.1: normal and income-elastic, a luxury — demand rises more than proportionally. -0.7: INFERIOR — demand FALLS as income rises, because consumers switch to a preferred substitute they can now afford. The error is reading 'inferior' as low quality. It is a statement about the sign of the income response, nothing else: bus travel and own-brand food are inferior for many consumers without being defective. Firms use this to forecast which product lines shrink in a boom."},
  "MC-MICRO-COMPETITION":{type:"distinguish",title:"Big Firm, or Monopoly?",instruction:"Decide whether each describes a monopoly, and give the actual test.",items:["A very large firm with many rivals", "The only supplier in a small local market", "A firm with 60% market share", "A firm with high total revenue"],answer:"Only the second is necessarily a monopoly, and the third meets the UK legal threshold. Size and revenue are irrelevant: a huge firm facing many rivals has little market power, and a tiny firm can be the only supplier in its market. The test is SHARE of a defined market and the ability to set price rather than take it. Barriers to entry are what let that persist — sunk costs, legal protection, control of an essential input, brand loyalty — and are not the same as 'the industry is expensive to be in', since a cost every firm faces equally deters nobody in particular. Competition's benefits run through the same logic: entry threat disciplines price and forces innovation."},
  "MC-MICRO-EXT-NEGATIVE":{type:"calculate",title:"Private, External, Social",instruction:"A factory's private cost of production is £40 per unit. Pollution imposes £15 per unit on nearby residents. Answer each part.",items:["What is the external cost?", "What is the social cost?", "At the free-market output, is production too high or too low?"],answer:"External cost = £15 — the cost falling on third parties, not on the producer. Social cost = private + external = £40 + £15 = £55. The single most common error is giving the social cost as £15; social cost is the WHOLE cost to society, so it includes the private cost. Because the firm decides on £40 and ignores the £15, marginal social cost exceeds marginal private cost and the free market OVER-produces relative to the social optimum, generating a deadweight welfare loss. Positive externalities run the mirror image: social benefit exceeds private benefit, so the market under-produces."},
  "MC-MICRO-PUBLIC-GOODS":{type:"distinguish",title:"Rival? Excludable?",instruction:"For each good, state whether it is rival and whether it is excludable, then name the category.",items:["National defence", "A cinema seat", "A congested public road", "Street lighting"],answer:"Defence: non-rival (my protection does not reduce yours) and non-excludable (cannot exclude a non-payer) — a PURE public good. Cinema seat: rival and excludable — a private good. Congested road: RIVAL (your use slows mine) but non-excludable — a quasi-public good, and the source of the tragedy of the commons. Street lighting: non-rival and non-excludable — public. The two properties are independent, which is why they must be tested separately rather than treated as one idea. Free-riding follows from non-excludability alone: if I cannot be excluded, my rational move is to consume without paying, so market provision collapses even though everyone values the good. That is a failure of incentives, not of honesty."},
  "MC-MICRO-CORRECTIVE-TAX":{type:"evaluate",title:"What Is the Tax For?",instruction:"A government taxes a polluting fuel. Evaluate each justification and identify the correct economic aim.",items:["It raises revenue for the Treasury", "It makes the polluter pay the external cost", "It punishes the firm", "It reduces output to the social optimum"],answer:"The economically correct aims are the second and fourth, which are the same argument: the tax internalises the externality by adding the external cost to the private cost, so the firm's private optimum moves to the social optimum. Revenue is a by-product, not the justification — a tax judged by revenue would be set at the wrong level, since a perfectly effective corrective tax that eliminated the harmful activity would raise nothing. 'Punishment' is not an economic category. Drawbacks worth knowing: the external cost is hard to value precisely, demand may be inelastic so output barely falls, and indirect taxes are regressive, taking a larger share of a low income."},
};
Object.keys(MC_ECON_STAGE2_MICRO).forEach(function (tag) {
  if (!MC_STARTERS[tag]) MC_STARTERS[tag] = MC_ECON_STAGE2_MICRO[tag];
});

// Stage 2, Theme 4 globalisation and trade.
var MC_ECON_STAGE2_GLOB = {
  "MC-GLOB-INTEGRATION":{type:"correct",title:"Does Globalisation Mean Convergence?",instruction:"A student writes: 'Globalisation means countries become equal.' Correct it, then define globalisation precisely.",items:["What the claim gets wrong", "A correct definition", "One piece of evidence either way"],answer:"Globalisation is the increasing INTERDEPENDENCE of economies through trade, investment, migration and information flows. It says nothing about equality. Some economies have converged sharply (South Korea, China, Vietnam) while others, particularly commodity-dependent ones, have not, and inequality WITHIN many countries has risen even as it fell between them. So the correct claim is about connection, not convergence. Trade liberalisation is the removal of barriers; economic integration is the deeper process of which a free-trade area, customs union and monetary union are successive stages. Interdependence cuts both ways: it transmits growth and it transmits shocks."},
  "MC-GLOB-MNC":{type:"evaluate",title:"Why Locate There?",instruction:"An MNC opens a plant in a developing economy. Rank these motives and say why 'cheap labour' alone is a weak answer.",items:["Lower unit labour costs", "Access to a growing domestic market", "Avoiding tariffs by producing inside the trade bloc", "Proximity to raw materials or suppliers"],answer:"All four are genuine, and an answer giving only cheap labour is weak because low wages usually accompany low productivity — what firms care about is unit labour cost, wages divided by output per worker, which can be higher in a low-wage economy. Market access is often the dominant motive for large emerging economies: the plant exists to sell there, not to export. Tariff-jumping explains location inside customs unions. Supply-chain proximity explains clustering. A transnational corporation is one that both owns and controls production in more than one country, which is what distinguishes it from a firm that merely exports."},
  "MC-GLOB-TARIFF":{type:"diagram",title:"Who Actually Pays the Tariff?",instruction:"A country imposes a tariff on imported steel. Work through who gains and who loses.",items:["Domestic steel producers", "Domestic consumers and steel-using firms", "The government", "Foreign exporters"],answer:"Domestic producers GAIN: the price rises, so they sell more at a higher price — producer surplus increases. Consumers and downstream firms LOSE, paying a higher price on every unit including domestically produced ones. The government gains tariff revenue on the units still imported. Foreign exporters lose volume. The key correction: the tariff is collected at the border but its INCIDENCE falls largely on domestic buyers, not on the foreign producer, whenever domestic demand is relatively inelastic. Net welfare typically falls because the production and consumption distortions (the two triangles) are not offset by the revenue rectangle. This is also why tariffs are a poor revenue tool: raise the rate and imports fall, so the base shrinks."},
  "MC-GLOB-GAINS":{type:"distinguish",title:"Static Gains, Dynamic Gains",instruction:"Sort these gains from trade into STATIC and DYNAMIC, and say why the distinction matters in a 12-mark answer.",items:["Reallocating output to the lower-opportunity-cost producer", "Greater competition forcing firms to cut costs over time", "Consumers accessing a wider variety at lower prices", "Technology transfer raising productivity growth"],answer:"Static gains are one-off improvements from reallocating existing resources: specialisation according to comparative advantage, and the immediate variety and price effects. Dynamic gains accumulate: competitive pressure driving cost reduction and innovation, economies of scale from a larger market, and technology transfer through FDI and supply chains raising the growth RATE rather than the level. The distinction matters because most exam answers stop at the static case and so understate the argument, while evaluation runs the other way — dynamic gains are the least certain and the slowest to appear, and they depend on institutions, infrastructure and absorptive capacity that the poorest economies often lack."},
  "MC-GLOB-PROTECTION":{type:"evaluate",title:"Who Bears the Cost?",instruction:"A government protects a declining domestic industry. List the gains and the costs, and say whose interests are visible and whose are not.",items:["Employment in the protected industry", "Prices paid by consumers", "Costs to firms using the product as an input", "Retaliation by trading partners"],answer:"The gain is concentrated and visible: jobs saved in one identifiable industry, in one region, with a name attached. The costs are diffuse and invisible: every consumer pays slightly more, every downstream firm faces higher input costs and so may shed more jobs than the policy saves, and partners may retaliate against unrelated exports. This asymmetry — concentrated benefit, dispersed cost — is why protection is politically durable and economically weak, and it is the evaluation point most answers miss. Also note the dynamic cost: shielded from competition, the protected industry has less incentive to raise productivity, so protection intended as temporary tends to become permanent."},
  "MC-GLOB-FDI":{type:"distinguish",title:"FDI or Portfolio?",instruction:"Classify each flow, then judge the host country's net gain.",items:["A firm builds and operates a factory abroad", "A fund buys 2% of a foreign company's shares", "A firm acquires a controlling stake in a foreign rival", "Profits sent home to the parent company"],answer:"FDI involves lasting interest and CONTROL — building the factory and acquiring the controlling stake. Portfolio investment is a financial holding without control, and matters because it is far more easily reversed: 'hot money' can leave in days, which is why economies reliant on it are crisis-prone. The fourth item is profit repatriation, and it is the reason the host country's gain is smaller than the headline investment. Inward FDI is a credit on the financial account and adds to productive capacity, skills and often exports; repatriated profit is a debit on the CURRENT account (primary income) in every later year. So the same project improves one account now and worsens another indefinitely."},
  "MC-GLOB-NONTARIFF":{type:"compare",title:"Tariff Against Quota",instruction:"Compare a tariff and an equivalent quota on the same import.",items:["Effect on domestic price", "Effect on government revenue", "Who captures the difference", "Effect if domestic demand later rises"],answer:"Both raise the domestic price and cut import volume, which is why they are treated as interchangeable — wrongly. A tariff generates government REVENUE. A quota generates none: the gap between world price and domestic price becomes quota rents captured by whoever holds the licences, often the foreign exporters themselves. That is a real transfer abroad. They also behave differently under growth: with a tariff, rising demand pulls in more imports at the tariffed price, while a quota holds volume fixed so the entire increase must come from domestic supply and the price rises further. Non-tariff barriers — standards, licensing, complex customs procedures — restrict trade without appearing as a tax at all, which makes them harder to negotiate away."},
  "MC-GLOB-DUMPING":{type:"distinguish",title:"Dumping, or Just Cheap?",instruction:"Decide which of these is dumping under trade rules, and state the test.",items:["Imports cheaper than domestic goods because wages abroad are lower", "Imports sold below their cost of production", "Imports cheaper because of genuine comparative advantage", "Exports subsidised by the exporting government"],answer:"Only the second is dumping: selling in a foreign market below cost of production, or below the price charged at home. The test is the relationship between price and the exporter's OWN cost or home price — not whether the import undercuts domestic producers, which is what ordinary comparative advantage looks like and is the whole point of trade. Lower foreign wages are not dumping. An export subsidy is a distinct practice, countervailable separately. The distinction matters because 'they are dumping' is the standard rhetorical cover for protecting an industry that is simply less competitive, and an exam answer that cannot state the cost test cannot evaluate the claim."},
  "MC-GLOB-CREATION-DIVERSION":{type:"distinguish",title:"Creation or Diversion?",instruction:"A country joins a customs union. Classify each outcome and say what determines which dominates.",items:["It now imports from a lower-cost member instead of producing domestically", "It now imports from a member instead of a cheaper non-member", "Consumers gain from lower prices within the bloc", "The common external tariff raises the price of non-member goods"],answer:"Trade CREATION: production shifts from a high-cost domestic producer to a lower-cost member — genuinely welfare-improving, since the same good is now made where it costs less. Trade DIVERSION: imports shift from a low-cost NON-member to a higher-cost member purely because the external tariff makes the efficient supplier artificially expensive — welfare-reducing, since resources move to a less efficient producer. The net effect determines whether joining is beneficial, so a bloc is not automatically good. Diversion dominates when members are high-cost relative to the outside world and the common external tariff is high."},
  "MC-GLOB-CURRENT-ACCOUNT":{type:"classify",title:"Which Account, Which Sign?",instruction:"Place each item in the right part of the balance of payments with the right sign.",items:["A UK firm exports machinery", "A UK resident receives dividends from shares held abroad", "A German fund buys UK government bonds", "A UK tourist spends money in Spain"],answer:"Machinery export: current account, trade in GOODS, credit. Dividends from abroad: current account, PRIMARY INCOME, credit — income is part of the current account, which is why the balance of trade is only one component of it. Bond purchase by a foreign fund: FINANCIAL account, credit (an inflow of capital). Tourist spending abroad: current account, trade in SERVICES, debit. The four parts of the current account are goods, services, primary income and secondary income (transfers). A current account deficit is not debt — it is a flow over a period, financed by a corresponding financial account surplus, which is why the overall balance of payments always sums to zero."},
  "MC-GLOB-ER-REGIME":{type:"compare",title:"Floating Against Fixed",instruction:"Compare the two regimes on each dimension.",items:["How the rate is determined", "What the central bank must hold", "Freedom to set domestic interest rates", "Response to an external shock"],answer:"Floating: determined by supply and demand for the currency; no reserves needed to defend it; monetary policy stays free for domestic objectives; the rate itself absorbs shocks by moving. Fixed: the central bank commits to a parity and must buy or sell its own currency to hold it, which requires substantial foreign exchange RESERVES and subordinates interest rates to defending the peg — raise rates to defend the currency even in a recession. The shock is then absorbed by output and employment instead of by the exchange rate. So the trade-off is certainty for exporters and importers against the loss of independent monetary policy, and a peg is only as credible as the reserves behind it."},
  "MC-GLOB-ER-EFFECTS":{type:"chain",title:"Depreciation to the Current Account",instruction:"Build the chain from a depreciation to the current account, then state the two conditions under which it fails.",items:["Export prices in foreign currency fall", "Import prices in domestic currency rise", "Export volumes rise, import volumes fall", "The current account improves"],answer:"The chain is right but conditional. Prices change IMMEDIATELY; volumes adjust slowly, because contracts are signed and buyers cannot switch overnight. So in the short run the higher import bill dominates and the account WORSENS before improving — the J-curve. The formal condition is Marshall-Lerner: the sum of the price elasticities of demand for exports and imports must exceed 1. Two failure cases: elasticities stay low (commodity importers with no substitute for fuel), and imported inputs feed through into domestic costs, raising export prices and cancelling the competitiveness gain. An appreciation runs in reverse, which is why it reduces inflation — imports become cheaper in domestic currency."},
  "MC-GLOB-INFANT":{type:"evaluate",title:"The Infant Industry Case",instruction:"Evaluate protection for a new domestic industry. What must be true for the argument to work, and what usually goes wrong?",items:["The industry will reach competitive scale", "Protection is temporary and declining", "The government can identify which industries qualify", "The industry lobbies to keep protection"],answer:"The argument is valid in principle: an industry with large economies of scale or a learning curve may be unable to enter against established foreign incumbents, so temporary protection buys time to reach efficient scale. It requires a credible EXIT condition — protection that declines on a published timetable — and the ability to pick industries that will actually succeed. What goes wrong is predictable: protection creates a constituency with a concentrated interest in keeping it, governments have no better information than markets about which industries will succeed, and shielded firms have weaker incentives to reach competitiveness. So the honest evaluation is that the theory is sound and the implementation record is poor."},
  "MC-GLOB-INEQUALITY":{type:"evaluate",title:"Aggregate Gains, Uneven Gains",instruction:"Trade raises a country's total income. Explain why that is consistent with many people being worse off.",items:["Workers in import-competing industries", "Workers in exporting industries", "Consumers of imported goods", "Owners of capital in exporting sectors"],answer:"Comparative advantage predicts that a country GAINS IN AGGREGATE, not that every person gains. Trade reallocates production towards sectors of comparative advantage, so workers in import-competing industries face falling demand for their specific skills, in specific regions, often with limited mobility — their losses are concentrated and persistent. Exporting sectors and consumers gain, and those gains are widely spread and individually small. Because the winners' gains exceed the losers' losses, compensation is possible in principle; it is rarely delivered in practice, which is the real content of the political backlash. This is also why 'trade is good for the country' and 'trade destroyed my town' can both be true."},
  "MC-GLOB-DEV-FINANCE":{type:"compare",title:"Four Ways Money Arrives",instruction:"Compare these inflows to a developing economy on reliability, cost and conditions attached.",items:["Remittances from migrant workers", "Official development aid", "Foreign commercial borrowing", "Sovereign wealth fund investment"],answer:"Remittances: large, remarkably stable, counter-cyclical (they rise when the home economy struggles) and free of conditions — but they go to households, not to public investment. Aid: may be tied to purchases from the donor, which cuts its real value well below the headline figure, and often carries policy conditionality. Commercial borrowing: available at scale but creates a repayment obligation, usually in foreign currency, so a depreciation raises the domestic cost of servicing it — the mechanism behind most debt crises. Sovereign wealth investment brings capital and sometimes strategic dependence. The common error is treating all four as costless inflows; each has a different claim attached to it and a different behaviour in a downturn."},
};
Object.keys(MC_ECON_STAGE2_GLOB).forEach(function (tag) {
  if (!MC_STARTERS[tag]) MC_STARTERS[tag] = MC_ECON_STAGE2_GLOB[tag];
});

// Stage 2, Theme 3 firms, revenue and costs.
var MC_ECON_STAGE2_FIRM = {
  "MC-FIRM-GROWTH-MOTIVE":{type:"evaluate",title:"Does Growing Raise Profit?",instruction:"A firm doubles output. Give a reason profit rises and a reason it falls, then state what decides it.",items:["Fixed costs spread over more units", "Bulk buying and specialised capital", "Communication and coordination costs rise", "Managers pursue size for its own sake"],answer:"Profit rises if long-run average cost falls — economies of scale from spreading fixed costs, bulk purchasing, specialised capital and cheaper finance. Profit falls if the firm passes minimum efficient scale into DISECONOMIES: communication failures, coordination costs, weaker motivation in a larger hierarchy. What decides it is where the firm sits on its long-run average cost curve, plus whether demand exists for the extra output — doubling output into a market that will not absorb it cuts price and margin together. The fourth item is the honest answer to many real cases: growth can serve managers' interests rather than owners', which is the principal-agent problem."},
  "MC-FIRM-OBJECTIVES":{type:"classify",title:"What Is the Firm Maximising?",instruction:"Match each behaviour to the objective it reveals.",items:["Producing where MC = MR", "Cutting price to raise total revenue", "Accepting adequate profit to avoid risk and effort", "Pricing to survive a recession at any margin"],answer:"MC = MR is PROFIT maximisation, the standard assumption. Cutting price to raise total revenue is REVENUE maximisation, which occurs where MR = 0 and typically means a lower price and higher output than profit maximisation. Accepting adequate profit is SATISFICING — meeting a target that keeps stakeholders content rather than optimising, which is rational once managers bear the effort and risk personally. The last is survival, which dominates in a downturn or for a new entrant. The error is treating profit maximisation as a fact rather than a modelling assumption: which objective applies changes the predicted price and output, so an evaluation question turns on it."},
  "MC-FIRM-PRINCIPAL-AGENT":{type:"diagnose",title:"Whose Interest Is Served?",instruction:"In each case, identify the principal, the agent, and the conflict.",items:["Managers expand the firm while profits fall", "A director takes a risky bet near retirement", "Shareholders demand dividends; managers want retained earnings", "A sales team paid on volume discounts heavily"],answer:"In each, the PRINCIPAL delegates to an AGENT whose interests differ and whose actions cannot be fully observed — the divorce of ownership from control. Managers may prefer size, since salary, status and security track the firm's scale rather than its profit. A departing director bears little of the downside of a risky bet. Retained earnings fund growth managers value; dividends serve shareholders' returns. Volume-based pay makes discounting rational for the salesperson and costly for the firm. The common structure is asymmetric information plus misaligned incentives, and the standard remedies — share options, performance pay, monitoring — work by realigning payoffs, not by exhortation."},
  "MC-FIRM-MARKET-SHARE":{type:"calculate",title:"Share, Sales, Loyalty",instruction:"Firm A sells £30m in a market worth £200m. Firm B sells £45m in a market worth £500m. Answer each part.",items:["Which firm has the larger market share?", "Which has the larger absolute sales?", "Does a high share prove customer loyalty?"],answer:"Share: A has 30/200 = 15%; B has 45/500 = 9%. So A has the larger SHARE while B has the larger absolute SALES — the two questions have opposite answers, which is exactly why they must be kept apart. Market share is always relative to a defined market, so the definition of that market does much of the work. And a high share does not prove loyalty: it may rest on limited choice, high switching costs, distribution control or inertia. Loyalty is revealed by what happens when a rival enters or a price rises — a firm with high share and weak loyalty loses it fast, which is the risk in a contestable market."},
  "MC-FIRM-EXTERNAL-GROWTH":{type:"distinguish",title:"Which Kind of Integration?",instruction:"Classify each deal and state the main motive.",items:["A supermarket buys a rival supermarket", "A brewery buys the pubs that sell its beer", "A car maker buys its steel supplier", "A tobacco firm buys a food company"],answer:"Supermarket buying a rival: HORIZONTAL — same industry, same stage. Motive is market share and scale economies; this is where competition authorities look. Brewery buying pubs: FORWARD VERTICAL, towards the customer — securing distribution and capturing the retail margin. Car maker buying its steel supplier: BACKWARD VERTICAL, towards the raw material — securing supply and input cost. Tobacco buying food: CONGLOMERATE, unrelated — diversification to spread risk across uncorrelated markets. A takeover is the MECHANISM (acquiring control of another firm) and integration describes the DIRECTION; they answer different questions, which is why using them interchangeably loses marks."},
  "MC-FIRM-EOS-SOURCES":{type:"classify",title:"Which Economy Is This?",instruction:"Name the source of the cost advantage in each case.",items:["A large firm borrows at a lower interest rate than a small one", "A supermarket sells insurance using its existing brand and stores", "A firm uses a specialised machine viable only at high output", "A conglomerate's divisions offset each other's risk"],answer:"Lower borrowing cost is a FINANCIAL economy of scale — lenders see a large firm as lower risk and better collateralised. The specialised machine is a TECHNICAL economy of scale, viable only above a threshold output. Risk offsetting across divisions is a RISK-BEARING economy. The supermarket case is different in kind: it is an economy of SCOPE, a cost advantage from producing several products together by sharing an asset — brand, distribution, data — rather than from producing more of one thing. Scale is about volume of one output; scope is about breadth of outputs. Both lower average cost, and treating them as one idea hides which lever a firm is actually pulling."},
  "MC-FIRM-CONTESTABILITY":{type:"distinguish",title:"Sunk, or Just Fixed?",instruction:"Decide whether each cost is sunk, fixed, both or neither, and say what that implies for entry.",items:["Rent on a leased warehouse, cancellable monthly", "A national advertising campaign", "A specialised machine with no resale market", "A fleet of standard vans"],answer:"Fixed means it does not vary with output; SUNK means it cannot be recovered on exit. Cancellable rent is fixed but not sunk. The advertising campaign is sunk the moment it is spent — nothing is recoverable. The specialised machine is fixed AND sunk, since it has no resale value. Standard vans are fixed but recoverable, so not sunk. This is the heart of contestability: entry is deterred by SUNK costs, not by fixed costs, because a potential entrant fears being unable to leave without loss. A market with high fixed but low sunk costs can be highly contestable even with one incumbent, and the threat of entry alone disciplines its pricing. So counting the firms in a market tells you little."},
  "MC-FIRM-COMPETITION-STRATEGY":{type:"classify",title:"Competing Without Cutting Price",instruction:"Classify each action and explain why non-price competition is still competition.",items:["Extending a warranty from one year to three", "Matching a rival's advertised price", "Redesigning packaging and branding", "Adding free next-day delivery"],answer:"All except the second are NON-PRICE competition: warranty, branding and delivery all raise the value of the offer rather than lowering its price. Only price matching is price competition. Non-price competition is what firms use where products are differentiated or where price cuts would simply be matched, triggering a price war that leaves shares unchanged and margins lower — the standard oligopoly outcome. It is competition because it does the same job: attracting customers from rivals. It is often preferred because a warranty or brand is harder and slower for a rival to copy than a price cut, so the advantage lasts. A price leader is a distinct idea: the firm whose price change others follow."},
  "MC-FIRM-NONPROFIT-FORMS":{type:"distinguish",title:"Who Owns It, Who Gets the Surplus?",instruction:"For each organisation, state who owns it and where any surplus goes.",items:["A public limited company", "A workers' cooperative", "A social enterprise", "A charity"],answer:"PLC: owned by shareholders, surplus distributed as dividends or retained for growth. Cooperative: owned by its members — workers, or customers — with surplus shared among them or reinvested, and typically one member one vote rather than one share one vote. Social enterprise: trades commercially but reinvests the majority of its surplus in its social mission. Charity: no owners; surplus must go to the stated purpose. The error to correct is the belief that these organisations do not need a surplus. All of them do — a social enterprise that consistently loses money closes and delivers nothing. The difference is not whether surplus is earned but who has a claim on it."},
  "MC-COST-PROFIT-CALC":{type:"calculate",title:"Totals, Averages, and Per Unit",instruction:"A firm sells 6,000 units. Total revenue is £90,000, total cost is £72,000. Answer each part.",items:["Total profit", "Average revenue and average cost", "Profit per unit, two different ways", "Why AR is also the price"],answer:"Total profit = TR - TC = £90,000 - £72,000 = £18,000. AR = 90,000/6,000 = £15; AC = 72,000/6,000 = £12. Profit per unit either as AR - AC = £15 - £12 = £3, or as total profit / output = 18,000/6,000 = £3. The two routes must agree, and checking that they do catches the common slip of subtracting a total from an average. AR is the price whenever every unit sells at the same price, because AR = TR/Q = (P x Q)/Q = P — worth deriving once, because it is what lets you read price straight off an average revenue curve."},
  "MC-COST-REVENUE":{type:"distinguish",title:"Total, Average, Marginal",instruction:"Define each revenue concept and state the relationship between them.",items:["Total revenue", "Average revenue", "Marginal revenue", "Why MR is below AR for a price-maker"],answer:"Total revenue = price x quantity, the whole amount received. Average revenue = TR/Q, which equals price when all units sell at the same price — so the AR curve IS the demand curve. Marginal revenue = the change in TR from selling one more unit. For a price TAKER, extra units sell at the unchanged market price, so MR = AR = price. For a price MAKER facing a downward-sloping demand curve, selling one more unit requires cutting the price on EVERY unit, not just the last one; the gain from the extra unit is partly offset by the loss on all the others, so MR lies BELOW AR and falls twice as steeply. Assuming MR always equals price is the error that makes the profit-maximising output come out wrong."},
  "MC-COST-NORMAL-PROFIT":{type:"calculate",title:"Is This Firm Profitable?",instruction:"An owner leaves a £40,000 salary to run a business. It earns £250,000 revenue with £220,000 of explicit costs. Work through each part.",items:["Explicit and implicit costs", "Accounting profit", "Economic profit", "Is the firm making normal profit?"],answer:"Explicit costs are the £220,000 actually paid out. The implicit cost is the £40,000 salary forgone — a genuine opportunity cost, paid in alternatives rather than money. Accounting profit = 250,000 - 220,000 = £30,000. Economic profit = 250,000 - (220,000 + 40,000) = -£10,000. So the business looks profitable to an accountant and is destroying £10,000 of value: the owner would be better off taking the job. NORMAL profit is the level that exactly covers all costs including implicit ones — economic profit of zero — and it is the minimum needed to keep resources in this use. Reading normal profit as 'no profit' inverts the meaning: a firm earning normal profit is doing exactly well enough to stay."},
};
Object.keys(MC_ECON_STAGE2_FIRM).forEach(function (tag) {
  if (!MC_STARTERS[tag]) MC_STARTERS[tag] = MC_ECON_STAGE2_FIRM[tag];
});

// Stage 2, Theme 2 policy, inequality and the financial sector.
var MC_ECON_STAGE2_MACRO = {
  "MC-INF-RATE-VS-LEVEL":{type:"calculate",title:"Rate, Level, Index",instruction:"CPI moves from 120 to 126 over a year. Answer each part.",items:["The inflation rate", "What happens to prices if the rate falls to 2% next year", "If 2015 = 100 and the basket cost £80 then and £104 now, the index now"],answer:"Inflation rate = (126 - 120)/120 x 100 = 5%. If the rate falls to 2%, prices are still RISING, just more slowly — the level keeps climbing. Prices only fall when the rate goes negative, which is deflation. This is the single most common macro error: reading a falling inflation rate as falling prices. Index: 104/80 x 100 = 130, meaning the basket costs 30% more than in the base year. An index number is a comparison with the base year, not a price in pounds. And 12% inflation is high but nowhere near hyperinflation, conventionally taken as 50% per MONTH."},
  "MC-INF-MEASUREMENT":{type:"correct",title:"What the CPI Actually Measures",instruction:"A student writes: 'The CPI basket always contains the same goods, and the 2% target is a maximum.' Correct both halves.",items:["Why the basket changes", "How weights work", "What the target actually is"],answer:"The basket is reviewed ANNUALLY and items are added and removed as spending patterns change — streaming subscriptions in, DVDs out. If it never changed it would stop measuring what households actually buy. Items are also WEIGHTED by their share of typical spending, so a 10% rise in housing costs moves the index far more than a 10% rise in the price of nutmeg. The Bank of England's 2% CPI target is symmetric: a point, not a ceiling. Missing it by more than one percentage point in EITHER direction requires the Governor to write to the Chancellor, because inflation persistently below target is also a policy failure, signalling weak demand."},
  "MC-INF-COSTPUSH":{type:"classify",title:"Which Cost Is Pushing?",instruction:"List cost-push sources beyond wages, then explain the wage-price spiral.",items:["Imported raw material and energy prices", "A depreciation raising import costs", "Higher indirect taxes", "Falling labour productivity"],answer:"Cost-push inflation is any rise in the cost of production shifting SRAS left — output falls and the price level rises together, which is why it is harder to treat than demand-pull. Wages are one source among several: commodity and energy prices, a depreciation raising the domestic cost of every import, indirect taxes, and falling productivity (which raises unit labour costs even if wages are flat). The spiral: prices rise, so real wages fall, so workers bargain for higher nominal wages; firms facing higher wage costs raise prices again. It is self-sustaining only if expectations become unanchored, which is why central banks care about expected inflation as much as current inflation."},
  "MC-EMP-LABOUR-SUPPLY":{type:"diagram",title:"Shifting Labour Supply",instruction:"Net inward migration of working-age people rises. Work through the labour market diagram.",items:["Which curve shifts, and which way", "Effect on the equilibrium real wage", "Effect on total employment", "Why the effect on wages may be smaller than predicted"],answer:"Labour SUPPLY shifts RIGHT — more workers available at each wage. Taken alone, that lowers the equilibrium real wage and raises equilibrium employment. But the prediction is incomplete: migrants also consume, so aggregate demand rises and labour DEMAND shifts right too, offsetting the wage effect. Empirically the wage effect is small and concentrated in sectors where migrants compete most directly. Note this is a SHIFT, not a movement along: the wage did not change first. Contrast with a minimum wage set above equilibrium, which does not shift either curve — it imposes a floor, creating excess supply as the gap between quantity supplied and demanded at that wage."},
  "MC-MON-TRANSMISSION":{type:"chain",title:"From Base Rate to AD",instruction:"The MPC cuts the base rate by one percentage point. Trace the channels to aggregate demand.",items:["Borrowing and saving incentives", "Existing mortgage holders' disposable income", "Business investment appraisal", "The exchange rate"],answer:"Four channels, and an answer naming fewer is incomplete. Cheaper borrowing and lower returns on saving raise consumption and credit-financed spending. Households on variable-rate mortgages see monthly payments fall, raising disposable income — which is why highly indebted households are most affected, and why the effect is stronger where variable-rate debt is common. Lower rates reduce the cost of capital, so marginal investment projects become viable. And lower rates make the currency less attractive, causing a depreciation that raises net exports. So AD rises through C, I and X-M together. Time lags of up to two years matter: policy acts on the economy as it will be, not as it is."},
  "MC-FIS-DEFINITION":{type:"classify",title:"Fiscal, Monetary, or Supply-Side?",instruction:"Classify each instrument and state who controls it.",items:["Changing the income tax rate", "Changing the base interest rate", "Increasing infrastructure spending", "Quantitative easing"],answer:"FISCAL: government spending and taxation, controlled by the Treasury — so income tax and infrastructure spending. MONETARY: interest rates and the money supply, controlled by the independent Bank of England — the base rate and QE. Infrastructure spending is the interesting case: it is fiscal, raises AD in the short run through the multiplier, AND raises long-run aggregate supply by improving productive capacity, so it is legitimately both demand-side and supply-side. Defining fiscal policy to include interest rates is the error to kill, and it matters because the two are set by different institutions with different objectives — which is the whole point of central bank independence."},
  "MC-FIS-STABILISERS":{type:"distinguish",title:"Automatic or Discretionary?",instruction:"Classify each and explain what makes stabilisers automatic.",items:["Unemployment benefit payments rise in a recession", "The Chancellor announces a VAT cut", "Income tax receipts fall as incomes fall", "A new infrastructure programme is legislated"],answer:"AUTOMATIC: benefit payments rising and tax receipts falling. No decision is taken — they follow mechanically from the existing structure of a progressive tax system and means-tested benefits, which is precisely what makes them automatic. They cushion incomes immediately, with no recognition, decision or implementation lag. DISCRETIONARY: the VAT cut and the infrastructure programme, both requiring an active choice. The advantage of stabilisers is timing — they act at once and unwind on their own as recovery proceeds. Their limitation is that they moderate a downturn rather than reverse it, and they automatically widen the budget deficit in a recession, which is the intended behaviour and not evidence of failure."},
  "MC-FIS-TAX-REVENUE":{type:"evaluate",title:"Does a Higher Rate Raise More?",instruction:"Use the Laffer curve to evaluate 'raising the tax rate always raises revenue.'",items:["At a 0% rate", "At a 100% rate", "At a low rate, raised slightly", "Beyond the revenue-maximising rate"],answer:"Revenue = rate x base, and the error is treating the base as fixed. At 0% revenue is zero. At 100% revenue is also (approximately) zero, since nobody works for nothing — so revenue must rise then fall, giving the inverted-U Laffer curve. From a LOW rate, an increase raises revenue: the rate effect dominates. BEYOND the revenue-maximising rate, further increases reduce revenue as the base shrinks through reduced effort, avoidance, evasion and relocation. The honest evaluation: the shape is uncontroversial, the LOCATION of the peak is disputed and varies by tax, so 'we are past the peak' is an empirical claim requiring evidence, not a theoretical one. Note also that a question about raising revenue is not answered by discussing what the revenue is spent on."},
  "MC-FIS-LIMITS":{type:"distinguish",title:"Deficit or Debt?",instruction:"Distinguish the two, then give three limitations of fiscal policy.",items:["The budget deficit", "The national debt", "The relationship between them", "Three practical limitations"],answer:"The DEFICIT is a FLOW: the amount by which spending exceeds revenue in one year. The DEBT is a STOCK: the accumulated total owed, the sum of all past deficits less surpluses. So a falling deficit still ADDS to the debt — the debt only falls when the budget is in surplus. Confusing them makes 'we cut the deficit but debt rose' look like a contradiction when it is arithmetic. Limitations: time lags (recognition, decision, implementation) mean stimulus can arrive after recovery has begun; crowding out, if borrowing raises interest rates and displaces private investment; and political constraints, since spending is easier to raise than to cut. Add the multiplier's size, which is uncertain and smaller when import propensity is high."},
  "MC-FIS-CROWDING-OUT":{type:"evaluate",title:"When Does Crowding Out Bite?",instruction:"Evaluate whether expansionary fiscal policy crowds out private investment in each situation.",items:["The economy is at full employment", "The economy is deep in recession with spare capacity", "Interest rates are at the effective lower bound", "The government borrows from abroad"],answer:"At full employment, crowding out is strongest: resources are fully used, so extra government borrowing raises interest rates and bids resources away from private investment. In deep recession with spare capacity, it is weak or absent — idle resources are drawn in and the multiplier can even CROWD IN private investment as demand and confidence recover. At the lower bound, rates cannot rise much, so financial crowding out is minimal. Borrowing from abroad limits pressure on domestic rates but affects the exchange rate and creates a future income outflow. The evaluation point: crowding out is conditional on the output gap, so asserting it regardless of the cycle is the error."},
  "MC-MON-INDEPENDENCE":{type:"evaluate",title:"Why Not Let Ministers Set Rates?",instruction:"Explain what central bank independence means and why it is thought to help.",items:["Who sets the UK base rate", "What the government still decides", "The time-inconsistency problem", "One argument against independence"],answer:"The MPC of the Bank of England sets the base rate; the GOVERNMENT sets the 2% target. So independence is operational, not goal independence — a distinction worth stating precisely. The rationale is time inconsistency: a government facing an election has a short-run incentive to cut rates for a temporary boost, and because the public anticipates this, inflation expectations stay high and the policy loses effect. Delegating to a body with no electoral horizon makes the low-inflation commitment credible, which anchors expectations and lowers the cost of achieving it. Against: unelected officials making decisions with large distributional consequences, and a single inflation target can crowd out employment and financial stability objectives."},
  "MC-MON-LIMITS":{type:"evaluate",title:"What Interest Rates Cannot Fix",instruction:"Evaluate 'raising interest rates will solve inflation without trade-offs.'",items:["The effect on output and employment", "Time lags", "Cost-push inflation specifically", "The effective lower bound"],answer:"Higher rates reduce AD, so they reduce demand-pull inflation at the cost of lower output and higher unemployment — the trade-off is the mechanism, not a side effect. Lags of up to two years mean the MPC acts on forecasts and can tighten into a slowdown already under way. Against COST-PUSH inflation the tool is poorly matched: the cause is a leftward SRAS shift, so raising rates cuts demand into an economy already producing less, deepening the output loss without addressing the cost. The bank may still act to stop expectations unanchoring, which is a defensible but costly choice. Downward, the effective lower bound limits how much stimulus rates alone can deliver, which is why QE exists. Add liquidity-trap conditions, where confidence is so weak that cheaper credit is not taken up."},
  "MC-MON-QE":{type:"correct",title:"What QE Actually Does",instruction:"A student writes: 'QE means printing money to fund government spending.' Correct it and trace the mechanism.",items:["What the central bank actually buys", "Who it buys from", "How this affects yields and lending", "How forward guidance differs"],answer:"The central bank creates reserves electronically and buys ASSETS — mainly government bonds — on the SECONDARY market from pension funds, insurers and banks, not from the government at issue. That distinction is what separates QE from monetary financing. Buying bonds raises their price and so lowers their yield, pushing down long-term interest rates across the economy; investors rebalance into corporate bonds and equities, lowering borrowing costs for firms and raising wealth. Banks holding more reserves may lend more. Risks: asset price inflation benefiting existing asset holders, so worsening wealth inequality, and difficulty unwinding. Forward guidance is different again — no assets are bought; the bank shapes expectations by communicating the likely future path of rates."},
  "MC-SSP-DEMAND-VS-SUPPLY":{type:"classify",title:"Which Side of the Economy?",instruction:"Classify each policy, and identify the one that is genuinely both.",items:["Cutting the base rate", "Cutting income tax rates to sharpen work incentives", "Funding apprenticeships", "Building road and rail capacity"],answer:"Cutting the base rate is MONETARY and demand-side only — a common misclassification, since it works by raising C and I, not by raising productive capacity. Cutting income tax to improve incentives is supply-side in intent (raising labour supply and effort) while also raising disposable income and so AD. Apprenticeships are supply-side, raising human capital and shifting LRAS right. Infrastructure is genuinely BOTH: the construction spending raises AD now through the multiplier, and the finished capacity raises LRAS later. The test for a supply-side policy is whether it raises the economy's productive POTENTIAL, not whether the government spends money — classifying all government spending as supply-side is the error."},
  "MC-SSP-INTERVENTIONIST":{type:"distinguish",title:"Market-Based or Interventionist?",instruction:"Classify each supply-side policy and state the mechanism by which it raises LRAS.",items:["Government-funded vocational training", "Reducing trade union power", "Privatising a state industry", "State investment in research and development"],answer:"INTERVENTIONIST — government provides or funds directly: vocational training and R&D investment. MARKET-BASED — government removes barriers and lets markets operate: union reform and privatisation. Both aim to shift LRAS right, but by different routes. Training raises human capital, so output per worker rises. R&D raises the rate of technological progress. Union reform is argued to increase labour market flexibility and lower unit costs. Privatisation is argued to sharpen efficiency incentives. The important correction: these work through the SUPPLY side, raising potential output, even though training and R&D also raise AD as they are spent. Judging them by their demand effect alone misses their purpose."},
  "MC-SSP-LIMITS":{type:"evaluate",title:"Why Supply-Side Policy Disappoints",instruction:"Evaluate the effectiveness of supply-side policies in reducing unemployment.",items:["Time to take effect", "Cost and opportunity cost", "Whether unemployment is structural or cyclical", "Distributional effects"],answer:"Supply-side policies are slow: training a workforce or building infrastructure takes years, so they do little for someone unemployed today. They are costly, and interventionist versions carry an opportunity cost and an immediate fiscal impact. Their effectiveness depends entirely on the TYPE of unemployment: they address structural and frictional unemployment (skills mismatch, immobility, search) but not CYCLICAL unemployment caused by deficient demand, where retraining workers for jobs that do not exist achieves nothing. Some carry real distributional costs — reducing union power or trimming benefits may raise employment while lowering pay and security. The strongest evaluation states the condition: supply-side policy is necessary for the long run and insufficient in a recession."},
  "MC-INQ-MEASURES":{type:"calculate",title:"Reading Inequality",instruction:"Interpret each measure precisely.",items:["A Gini coefficient of 0.34", "A Lorenz curve further from the 45-degree line", "The richest quintile receiving 45% of income", "Why none of these measures poverty"],answer:"Gini runs from 0 (perfect equality, everyone has the same) to 1 (one person has everything), so 0.34 is moderate inequality — it is NOT an income level, a poverty rate or a percentage of poor people. A Lorenz curve bowed further from the line of perfect equality means GREATER inequality; the Gini is the ratio of the area between the curve and that line to the whole triangle. A top quintile taking 45% means 20% of people receive nearly half of all income, against 20% under equality. Crucially, all three measure DISTRIBUTION, not deprivation: a very poor country where everyone is equally poor has a low Gini. Inequality and poverty are distinct questions requiring distinct measures."},
  "MC-INQ-CAUSES":{type:"explain",title:"Cause, Then Evaluation",instruction:"Give one cause of UK income inequality and develop it properly, then say what an 8-mark answer needs beyond causes.",items:["State the cause", "Explain the mechanism", "Give evidence or an example", "Add the evaluation"],answer:"A worked example: skill-biased technological change. Mechanism — technology raises demand for high-skilled labour and substitutes for routine mid-skilled work, so wage returns to education rise while routine occupations decline, widening the gap. Evidence — the growing graduate wage premium and hollowing-out of mid-skill employment. That is a developed cause. But an 8-mark question rewards EVALUATION as well as knowledge and application, so an answer that lists causes without evaluating typically forfeits the evaluation marks — roughly a third to a half of the total. Evaluation here means weighing which cause dominates, noting counter-evidence (minimum wage effects compressing the lower tail), or questioning whether the trend is continuing."},
  "MC-INQ-REDISTRIBUTION":{type:"distinguish",title:"Progressive, Regressive, Proportional",instruction:"Classify each tax and state the test.",items:["Income tax with rising marginal rates", "VAT at a single rate on most goods", "A flat 20% tax on all income", "National Insurance above a threshold"],answer:"The test is the share of INCOME paid, not the amount. PROGRESSIVE: the share rises with income — income tax with rising marginal bands. REGRESSIVE: the share falls as income rises — VAT, because lower-income households spend a larger fraction of their income, so a single rate takes a bigger share of it even though richer households pay more in pounds. PROPORTIONAL: a constant share — the flat 20%. National Insurance is progressive at the threshold and regressive above the upper limit. The error is defining progressive as 'the rich pay more', which is true of almost every tax including regressive ones. Redistribution then works through the tax and benefit system TOGETHER: benefits do much of the work."},
  "MC-POV-ABSOLUTE-RELATIVE":{type:"distinguish",title:"Absolute or Relative?",instruction:"Classify each situation and explain why growth eliminates one more readily than the other.",items:["Income below a fixed subsistence basket", "Income below 60% of median income", "A household that cannot afford heating", "Poverty rate unchanged as all incomes double"],answer:"ABSOLUTE poverty is measured against a FIXED basket of necessities, so it falls as incomes rise — the first and third cases. RELATIVE poverty is measured against the CURRENT median of that society, so it captures exclusion from a normal standard of living. The fourth case is the decisive one: if all incomes double, absolute poverty collapses while relative poverty is UNCHANGED, because the median doubled too. This is why 'growth will automatically eliminate poverty' is only half right — growth is powerful against absolute poverty and does nothing for relative poverty unless the distribution shifts. It is also why relative poverty can rise during a boom and fall in a recession, when the median itself falls."},
  "MC-POV-TRAP":{type:"calculate",title:"Why Taking the Job Does Not Pay",instruction:"A claimant earning nothing receives £180 a week in benefits. A job pays £280. Benefits withdraw at 55p per £1 earned and income tax and NI take 32%.",items:["Benefit withdrawn", "Tax and NI paid", "Net gain from working", "The effective marginal rate"],answer:"Benefit withdrawn = 0.55 x 280 = £154. Tax and NI = 0.32 x 280 = £89.60 (ignoring allowances for the arithmetic). Gross gain £280, deductions £243.60, so the net gain is about £36 for a full working week. The effective marginal deduction rate is roughly 87%. That is the poverty or unemployment trap, and note what causes it: not low wages alone, but the WITHDRAWAL RATE at which benefits are removed interacting with the tax system. An answer blaming low pay alone misses the mechanism and therefore the policy response — lowering the taper rate, raising work allowances or increasing the personal allowance, all of which change the gradient rather than the wage."},
  "MC-FMK-02":{type:"explain",title:"How a Forward Contract Actually Works",instruction:"A UK importer owes $500,000 in three months. Explain what a forward contract does and why it is not speculation.",items:["What is agreed today", "What is settled later", "What risk is removed", "Why this is hedging, not betting"],answer:"Today the importer agrees a rate — say $1.25 per pound — for an exchange that will SETTLE in three months. No currency moves now; the rate is what is fixed. In three months the importer buys $500,000 at the agreed rate, paying £400,000 regardless of the spot rate then. The risk removed is exchange-rate uncertainty on a liability the firm ALREADY has: without the contract, a depreciation to $1.15 would raise the cost to £434,783. That is why it is hedging rather than speculation — the firm is offsetting an existing exposure, not creating a new one to profit from. The cost is giving up the gain if the rate moves favourably: certainty is bought by surrendering the upside."},
  "MC-BNK-FUNCTIONS":{type:"classify",title:"Commercial Bank or Central Bank?",instruction:"Assign each function to the right institution.",items:["Accepting deposits and making loans to households", "Setting the base interest rate", "Acting as lender of last resort", "Issuing banknotes and holding foreign exchange reserves"],answer:"COMMERCIAL banks: accepting deposits, lending, providing payment services — profit-making firms serving households and businesses. CENTRAL bank: setting the base rate, acting as lender of last resort, issuing currency, holding reserves, supervising the system and acting as banker to the government. Lender of last resort is the one worth understanding: the central bank lends to solvent but ILLIQUID banks in a crisis, which stops a liquidity problem at one bank becoming a system-wide collapse. It is not a rescue of a bank that is actually insolvent — that distinction is what the 2008 debates turned on. Note the Bank of England does NOT set fiscal policy or the tax system, a common distractor."},
  "MC-BNK-MONEY-CREATION":{type:"chain",title:"Where the Money Comes From",instruction:"A bank grants a £200,000 mortgage. Trace what happens on its balance sheet.",items:["Does the bank hand over existing deposits?", "What appears on the asset side", "What appears on the liability side", "What limits how much it can create"],answer:"The bank does NOT lend out pre-existing deposits. It credits the borrower's account, creating a new DEPOSIT (a liability) and simultaneously recording the LOAN as an asset. Both sides of the balance sheet expand by £200,000 and new broad money exists that did not before. That is the correction: the textbook picture of banks as intermediaries passing on savers' money describes only part of what happens. What limits creation is not a stock of deposits but profitability, creditworthy demand, capital requirements, liquidity rules and — ultimately — the central bank's policy rate, which sets the cost of the reserves banks need to settle payments between them. Repayment destroys money, which is why credit contraction shrinks the money supply."},
  "MC-BNK-MORAL-HAZARD":{type:"evaluate",title:"Was the Bailout Right?",instruction:"Evaluate the 2008 bank bailouts, then explain what regulation tried to fix.",items:["The case for rescuing", "The case against", "What moral hazard means here", "Post-crisis regulation"],answer:"FOR: banks are systemically connected, so an uncontrolled failure freezes payments and lending across the whole economy — the counterfactual was not one bank failing but a depression. AGAINST: public money rescued private losses after private gains, and it entrenched MORAL HAZARD — if a bank expects rescue, it has an incentive to take risks it would otherwise avoid, since the upside is private and the downside socialised. 'Too big to fail' names exactly that: a bank whose failure is intolerable cannot be credibly allowed to fail, so market discipline stops working on it. Regulation since has tried to attack the incentive rather than the symptom: higher capital and liquidity requirements, ring-fencing retail from investment banking, stress testing, and resolution regimes designed to let a large bank fail without taking the system down."},
  "MC-CB-FIN-STABILITY":{type:"distinguish",title:"MPC, FPC, or PRA?",instruction:"Assign each responsibility to the right Bank of England committee.",items:["Setting the base rate to meet the inflation target", "Identifying system-wide risks such as a credit bubble", "Setting limits on high loan-to-income mortgage lending", "Supervising the safety of individual banks and insurers"],answer:"MPC — Monetary Policy Committee: the base rate and QE, aimed at the 2% inflation target. FPC — Financial Policy Committee: MACROprudential regulation, watching risks to the system as a whole and using tools such as countercyclical capital buffers and mortgage lending limits. PRA — Prudential Regulation Authority: MICROprudential supervision of individual firms. The distinction the FPC exists to capture is that every bank can look individually sound while the system is fragile, because they are exposed to the same risks and to each other. Swapping the MPC and FPC is the standard error; the clue is the objective — price stability versus financial stability, which can point in opposite directions."},
};
